package ma.lias.controller;
import ma.lias.entity.*; import ma.lias.repository.*; import ma.lias.service.AuditService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/material-distributions")
public class MaterialDistributionController { private final MaterialDistributionRepository repo; private final MaterialInventoryRepository inventory; private final AuditService audit; public MaterialDistributionController(MaterialDistributionRepository repo, MaterialInventoryRepository inventory, AuditService audit){this.repo=repo;this.inventory=inventory;this.audit=audit;} @GetMapping public List<MaterialDistribution> all(){return repo.findAll();} @PostMapping public ResponseEntity<MaterialDistribution> create(@RequestBody MaterialDistribution body, org.springframework.security.core.Authentication auth){MaterialInventory item=inventory.findById(body.getMaterialId()).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,"Matériel introuvable")); if(body.getQuantity()<=0) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantité invalide"); if(item.getQuantity()<body.getQuantity()) throw new ResponseStatusException(HttpStatus.CONFLICT,"Stock insuffisant"); item.setQuantity(item.getQuantity()-body.getQuantity()); inventory.save(item); if(auth!=null && auth.getPrincipal() instanceof User u) body.setDistributedBy(u.getId()); MaterialDistribution saved=repo.save(body); audit.log("CREATE","MaterialDistribution",saved.getId(),"Distribution matériel avec décrément du stock"); return ResponseEntity.status(HttpStatus.CREATED).body(saved);} }
